<article class="print-sheet">
<header class="mb-6 flex items-start justify-between gap-5 border-b border-slate-300 pb-5"><div><p class="text-[10px] font-bold uppercase tracking-widest text-blue-700"><?= e($tenant['razonsocial']) ?> · NIT <?= e($tenant['nit']) ?></p><h1 class="mt-2 text-xl font-bold">Formato de reporte e investigación de evento SST</h1><p class="mt-1 text-xs text-slate-500"><?= e($event['codigo']) ?> · <?= e($event['tipo']) ?> · Estado <?= e($event['estado']) ?></p></div><p class="text-right text-[10px] text-slate-500">Impreso <?= date('Y-m-d H:i') ?><br>Uso interno</p></header>
<section class="mb-5"><h2 class="mb-2 text-sm font-bold">1. Datos del evento</h2><table class="w-full border-collapse text-[11px]"><tbody><?php foreach(['Fecha del evento'=>$event['fecha_evento'],'Hora del evento'=>$event['hora_evento'],'Fecha del reporte'=>$event['fecha_reporte'],'Lugar / centro'=>$event['lugar'],'Proceso / área'=>$event['proceso'],'Responsable de seguimiento'=>$event['responsable'],'Gravedad'=>$event['gravedad'],'Parte del cuerpo'=>$event['parte_cuerpo'],'Agente causante / factor de riesgo'=>$event['agente_causante'],'Días perdidos'=>(string)$event['dias_perdidos'],'Días cargados'=>(string)$event['dias_cargados']] as $label=>$value): ?><tr><th class="w-1/3 border border-slate-300 bg-slate-50 p-2 text-left"><?= e($label) ?></th><td class="border border-slate-300 p-2"><?= e($value?:'No registrado') ?></td></tr><?php endforeach; ?><tr><th class="border border-slate-300 bg-slate-50 p-2 text-left">Descripción objetiva</th><td class="border border-slate-300 p-2 whitespace-pre-line"><?= e($event['descripcion']) ?></td></tr><tr><th class="border border-slate-300 bg-slate-50 p-2 text-left">Lesión / condición necesaria</th><td class="border border-slate-300 p-2 whitespace-pre-line"><?= e($event['lesion']?:'No registrada') ?></td></tr></tbody></table></section>
<section class="mb-5"><h2 class="mb-2 text-sm font-bold">2. Personas y declaraciones</h2><?php if(!$people): ?><p class="text-xs">Sin personas vinculadas.</p><?php endif; ?><?php foreach($people as $person): ?><div class="mb-2 rounded border border-slate-300 p-3 text-[11px]"><strong><?= e($person['rol']) ?>: <?= e($person['nombre']) ?></strong><p>Documento: <?= e($person['documento']?:'No registrado') ?> · Vinculación: <?= e($person['vinculacion']?:'No registrada') ?></p><p class="mt-1 whitespace-pre-line"><?= e($person['declaracion']?:'Sin declaración registrada.') ?></p></div><?php endforeach; ?></section>
<section class="mb-5"><h2 class="mb-2 text-sm font-bold">3. Investigación y análisis causal</h2><?php if(!$investigation): ?><p class="text-xs">Investigación no iniciada.</p><?php else: ?><p class="mb-3 text-[11px]">Metodología: <?= e($investigation['metodologia']) ?> · Inicio <?= format_date($investigation['fecha_inicio']) ?> · Equipo: <?= e($investigation['equipo']) ?></p><?php foreach(['causas_inmediatas'=>'Causas inmediatas','causas_basicas'=>'Causas básicas','causas_administrativas'=>'Causas administrativas','analisis'=>'Análisis','conclusiones'=>'Conclusiones'] as $field=>$label): ?><div class="mb-2 text-[11px]"><strong><?= e($label) ?></strong><p class="whitespace-pre-line"><?= e($investigation[$field]?:'Pendiente') ?></p></div><?php endforeach; ?><div class="mb-2 text-[11px]"><strong>5 por qué</strong><ol class="ml-5 list-decimal"><?php foreach($investigation['cinco_porques'] as $why): ?><li><?= e($why?:'No diligenciado') ?></li><?php endforeach; ?></ol></div><div class="text-[11px]"><strong>Árbol de causas</strong><?php if(!$investigation['arbol_causas']): ?><p>No diligenciado.</p><?php endif; ?><ul class="mt-1"><?php foreach($investigation['arbol_causas'] as $node): ?><li style="margin-left:<?= min(8,(int)$node['nivel'])*18 ?>px">• <?= e($node['texto']) ?></li><?php endforeach; ?></ul></div><?php if($investigation['fecha_cierre']): ?><p class="mt-2 text-[10px]">Investigación cerrada el <?= format_date($investigation['fecha_cierre']) ?> por <?= e($investigation['elaborado_por_nombre']??'usuario registrado') ?>.</p><?php endif; ?><?php endif; ?></section>
<section class="mb-5"><h2 class="mb-2 text-sm font-bold">4. Acciones y eficacia</h2><table class="w-full border-collapse text-[10px]"><thead><tr><?php foreach(['Tipo','Acción','Responsable','Compromiso','Estado','Resultado / eficacia'] as $heading): ?><th class="border border-slate-300 bg-slate-50 p-2 text-left"><?= $heading ?></th><?php endforeach; ?></tr></thead><tbody><?php if(!$actions): ?><tr><td colspan="6" class="border border-slate-300 p-2">Sin acciones derivadas.</td></tr><?php endif; ?><?php foreach($actions as $action): ?><tr><td class="border border-slate-300 p-2"><?= e($action['tipo']) ?></td><td class="border border-slate-300 p-2"><?= e($action['descripcion']) ?></td><td class="border border-slate-300 p-2"><?= e($action['responsable']) ?></td><td class="border border-slate-300 p-2"><?= e($action['fecha_compromiso']) ?></td><td class="border border-slate-300 p-2"><?= e($action['estado']) ?></td><td class="border border-slate-300 p-2"><?= e($action['eficacia_resultado']?:'Pendiente') ?></td></tr><?php endforeach; ?></tbody></table></section>
<section class="mb-5 text-[11px]"><h2 class="mb-2 text-sm font-bold">5. Notificaciones externas registradas</h2><p>ARL: <?= e($event['reportado_arl_at']?:'No registrada') ?> · EPS: <?= e($event['reportado_eps_at']?:'No registrada') ?> · Ministerio: <?= e($event['reportado_mintrabajo_at']?:'No registrada') ?></p><p>Radicados/referencias: <?= e($event['radicados']?:'No registrados') ?></p></section>
<p class="border-t border-slate-300 pt-3 text-[9px] leading-4 text-slate-500">Este formato reproduce los datos internos registrados. No es por sí mismo el formulario oficial de una ARL o del Ministerio, no demuestra envío, recibido, diagnóstico ni calificación de origen, y requiere revisión humana antes de utilizarse en un canal oficial.</p>
